const HTML = "<!DOCTYPE html>\n<html lang=\"en\" id=\"top\">\n<head>\n<meta charset=\"UTF-8\">\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\">\n<title>TapeTrim \u2014 US Navy Body Fat Calculator (Tape Measure Method)</title>\n<meta name=\"description\" content=\"TapeTrim is a free US Navy body fat calculator: enter tape measurements (neck, waist, hip) and compare the Navy formula against the Deurenberg BMI estimate, see fat mass vs lean mass, set a target body-fat goal, and follow illustrated tape-placement guides.\">\n<script src=\"https://cdn.tailwindcss.com\"></script>\n<style>\n  :root{\n    --bg:#17130E; --bg2:#1F1810; --card:#221B11; --card2:#2A2115;\n    --line:#3D3220;\n    --yellow:#FFD60A; --yellow-dk:#D9A800;\n    --ink:#FAF6EF; --muted:#C9BFAE; --faint:#8F8471;\n    --danger:#FF6B5B; --ok:#7CE38B;\n  }\n  html{ scroll-behavior:smooth; }\n  body{ background:var(--bg); color:var(--ink); font-family:ui-sans-serif,system-ui,-apple-system,\"Segoe UI\",Roboto,Helvetica,Arial,sans-serif; }\n  .poster{ font-weight:900; letter-spacing:-0.02em; }\n  .kicker{ font-size:.72rem; letter-spacing:.28em; text-transform:uppercase; color:var(--yellow); font-weight:800; }\n  .card{ background:var(--card); border:1px solid var(--line); border-radius:1rem; box-shadow:0 10px 30px rgba(0,0,0,.35); }\n  .card-hi{ background:var(--card2); border:1px solid #4A3B22; border-radius:1rem; }\n  .field{ width:100%; background:#14100A; border:1px solid var(--line); border-radius:.65rem; padding:.65rem .8rem; font-size:1rem; color:var(--ink); font-variant-numeric:tabular-nums; }\n  .field:focus{ outline:2px solid var(--yellow); outline-offset:1px; border-color:var(--yellow); }\n  .field::placeholder{ color:#6E6350; }\n  label.lbl{ display:block; font-size:.7rem; letter-spacing:.12em; text-transform:uppercase; color:var(--muted); margin-bottom:.35rem; font-weight:700; }\n  .pill{ border:1px solid var(--line); border-radius:999px; padding:.5rem 1.15rem; font-weight:800; font-size:.85rem; letter-spacing:.04em; color:var(--muted); background:#14100A; transition:all .15s; cursor:pointer; }\n  .pill[aria-pressed=\"true\"]{ background:var(--yellow); border-color:var(--yellow); color:#17130E; }\n  .pill:hover{ border-color:var(--yellow); color:var(--ink); }\n  .pill[aria-pressed=\"true\"]:hover{ color:#17130E; }\n  .btn-primary{ background:var(--yellow); color:#17130E; border-radius:.75rem; padding:.8rem 1.6rem; font-weight:900; letter-spacing:.06em; text-transform:uppercase; font-size:.9rem; transition:transform .08s ease, background .15s; }\n  .btn-primary:hover{ background:#FFE14D; } .btn-primary:active{ transform:scale(.98); }\n  .btn-ghost{ border:1px solid var(--line); background:transparent; color:var(--muted); border-radius:.75rem; padding:.8rem 1.2rem; font-weight:700; font-size:.85rem; transition:all .15s; }\n  .btn-ghost:hover{ border-color:var(--yellow); color:var(--ink); }\n  .badge-free{ display:inline-flex; align-items:center; gap:.45rem; background:rgba(255,214,10,.1); color:var(--yellow); border:1px solid var(--yellow); font-size:.72rem; font-weight:800; letter-spacing:.08em; text-transform:uppercase; padding:.4rem .9rem; border-radius:999px; }\n  .tape-strip{ height:16px; background-color:var(--yellow);\n    background-image:\n      repeating-linear-gradient(90deg, rgba(23,19,14,.9) 0 2px, transparent 2px 12px),\n      repeating-linear-gradient(90deg, rgba(23,19,14,.9) 0 2px, transparent 2px 60px);\n    background-size:100% 8px, 100% 15px; background-position:bottom,bottom; background-repeat:repeat-x; }\n  .tape-strip-v{ width:16px; background-color:var(--yellow);\n    background-image:\n      repeating-linear-gradient(0deg, rgba(23,19,14,.9) 0 2px, transparent 2px 12px),\n      repeating-linear-gradient(0deg, rgba(23,19,14,.9) 0 2px, transparent 2px 60px);\n    background-size:8px 100%, 15px 100%; background-position:left,left; background-repeat:repeat-y; }\n  .giant{ font-size:clamp(4.5rem,14vw,8.5rem); line-height:.95; }\n  .num{ font-variant-numeric:tabular-nums; }\n  .diag{ background:#14100A; border:1px solid var(--line); }\n  .errbox{ border:1px solid var(--danger); background:rgba(255,107,91,.08); border-radius:.75rem; }\n  .faq-item{ border:1px solid var(--line); border-radius:.8rem; background:var(--card); overflow:hidden; }\n  .faq-a{ max-height:0; overflow:hidden; transition:max-height .25s ease; }\n  .faq-item.open .faq-a{ max-height:700px; }\n  .faq-item.open .faq-chev{ transform:rotate(180deg); }\n  .faq-chev{ transition:transform .2s; }\n  .zone-seg{ height:100%; }\n  .marker{ position:absolute; top:-6px; width:3px; height:calc(100% + 12px); background:var(--yellow); box-shadow:0 0 10px rgba(255,214,10,.9); }\n  .marker::after{ content:\"\"; position:absolute; top:-9px; left:50%; transform:translateX(-50%); border:7px solid transparent; border-top-color:var(--yellow); }\n  .dropcap::first-letter{ font-family:Georgia,serif; font-size:3.2em; float:left; line-height:.9; padding-right:.12em; color:var(--yellow); font-weight:700; }\n  .no-print{}\n  @media print{ .no-print{ display:none !important; } }\n  input[type=range].tslider{ accent-color:var(--yellow); width:100%; }\n  .switch{ position:relative; width:46px; height:26px; border-radius:999px; background:#3D3220; transition:background .15s; flex:none; cursor:pointer; border:1px solid var(--line); }\n  .switch::after{ content:\"\"; position:absolute; top:2px; left:2px; width:20px; height:20px; border-radius:50%; background:#8F8471; transition:all .15s; }\n  .switch[aria-checked=\"true\"]{ background:var(--yellow); border-color:var(--yellow); }\n  .switch[aria-checked=\"true\"]::after{ left:22px; background:#17130E; }\n  .hist-chip{ cursor:pointer; }\n  .hist-chip:hover{ border-color:var(--yellow); }\n  ::selection{ background:var(--yellow); color:#17130E; }\n</style>\n</head>\n<body class=\"antialiased\">\n\n<!-- ============ STICKY HEADER ============ -->\n<header class=\"sticky top-0 z-40 border-b\" style=\"background:rgba(23,19,14,.96); border-color:var(--line); backdrop-filter:blur(6px);\">\n  <div class=\"mx-auto max-w-6xl px-4 sm:px-6 h-16 flex items-center justify-between\">\n    <a href=\"#top\" class=\"flex items-center gap-2.5\" aria-label=\"TapeTrim home\">\n      <svg width=\"32\" height=\"32\" viewBox=\"0 0 32 32\" aria-hidden=\"true\">\n        <rect x=\"2\" y=\"9\" width=\"28\" height=\"14\" rx=\"3\" fill=\"#FFD60A\"/>\n        <rect x=\"2\" y=\"9\" width=\"28\" height=\"14\" rx=\"3\" fill=\"none\" stroke=\"#17130E\" stroke-width=\"1.6\"/>\n        <path d=\"M7 12v3M11 12v5M15 12v3M19 12v5M23 12v3M27 12v5\" stroke=\"#17130E\" stroke-width=\"1.8\"/>\n        <circle cx=\"25.5\" cy=\"16\" r=\"2.6\" fill=\"#17130E\"/>\n      </svg>\n      <span class=\"poster text-2xl tracking-tight\" style=\"color:var(--ink);\">Tape<span style=\"color:var(--yellow);\">Trim</span></span>\n    </a>\n    <nav class=\"flex items-center gap-5 text-sm font-semibold\">\n      <a href=\"#top\" class=\"hover:underline\" style=\"color:var(--ink);\">Home</a>\n      <a href=\"https://fixoraa.tech\" class=\"hover:underline\" style=\"color:var(--yellow);\">More Tools</a>\n    </nav>\n  </div>\n</header>\n\n<!-- ============ TOP AD ============ -->\n<div class=\"no-print mx-auto max-w-6xl px-4 sm:px-6 pt-4\" role=\"complementary\" aria-label=\"Advertisement\">\n  <div class=\"mx-auto text-center\" style=\"max-width:728px\">\n    <span class=\"block text-[10px] tracking-[0.18em] uppercase text-slate-400 mb-1.5\">Advertisement</span>\n    <div class=\"flex justify-center overflow-hidden\">\n      <div class=\"origin-top scale-[0.44] sm:scale-100 shrink-0\">\n        <script>\n          atOptions = { 'key' : '4e68ac77881c17fe128a46565d9a4e8c', 'format' : 'iframe', 'height' : 90, 'width' : 728, 'params' : {} };\n        </script>\n        <script src=\"https://www.highrevenueformat.com/4e68ac77881c17fe128a46565d9a4e8c/invoke.js\"></script>\n      </div>\n    </div>\n  </div>\n</div>\n\n<!-- ============ HERO ============ -->\n<section class=\"relative overflow-hidden\">\n  <div class=\"tape-strip\"></div>\n  <div class=\"mx-auto max-w-6xl px-4 sm:px-6 pt-10 pb-8 sm:pt-14 sm:pb-10\">\n    <div class=\"flex flex-col lg:flex-row lg:items-end gap-8\">\n      <div class=\"flex-1\">\n        <p class=\"kicker mb-3\">No calipers \u00b7 No scales \u00b7 No guesswork</p>\n        <h1 class=\"poster uppercase\" style=\"font-size:clamp(2.6rem,8vw,5.2rem); line-height:.95;\">\n          Measure it.<br><span style=\"color:var(--yellow);\">Trim it.</span>\n        </h1>\n        <p class=\"mt-4 max-w-xl text-base sm:text-lg\" style=\"color:var(--muted);\">\n          TapeTrim runs the <strong style=\"color:var(--ink);\">US Navy tape-measure method</strong> on your neck, waist and hip \u2014\n          then cross-checks it against the <strong style=\"color:var(--ink);\">Deurenberg BMI formula</strong>,\n          maps your result on the fitness scale, and tells you exactly how much fat to lose to hit your goal.\n        </p>\n        <div class=\"mt-5 flex flex-wrap items-center gap-3\">\n          <span class=\"badge-free\"><svg width=\"14\" height=\"14\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><path d=\"M13 2L3 14h7l-1 8 10-12h-7l1-8z\"/></svg>Unlimited Free Usage</span>\n          <span class=\"text-xs\" style=\"color:var(--faint);\">No signup \u00b7 No paywall \u00b7 Everything runs in your browser</span>\n        </div>\n      </div>\n      <div class=\"hidden lg:flex flex-col items-center gap-2 pr-4\" aria-hidden=\"true\">\n        <div class=\"poster num\" style=\"font-size:5.5rem; color:var(--yellow);\" id=\"hero_tease\">\u2013%</div>\n        <div class=\"text-xs uppercase tracking-[0.25em]\" style=\"color:var(--faint);\">body fat</div>\n      </div>\n    </div>\n  </div>\n  <div class=\"tape-strip\"></div>\n</section>\n\n<!-- ============ TOOL ============ -->\n<main class=\"mx-auto max-w-6xl px-4 sm:px-6 py-8 sm:py-10\">\n  <div id=\"errors\" class=\"errbox hidden mb-5 p-4 text-sm\" role=\"alert\"></div>\n\n  <div class=\"grid gap-6 lg:grid-cols-5\">\n    <!-- ===== INPUTS ===== -->\n    <section class=\"card p-5 sm:p-7 lg:col-span-2\" aria-label=\"Your measurements\">\n      <h2 class=\"poster text-xl uppercase mb-1\">Your <span style=\"color:var(--yellow);\">tape data</span></h2>\n      <p class=\"text-xs mb-5\" style=\"color:var(--faint);\">Grab a soft tape measure. See the placement guide below.</p>\n\n      <div class=\"mb-5\">\n        <label class=\"lbl\">Sex</label>\n        <div class=\"flex gap-2\" role=\"group\" aria-label=\"Sex\">\n          <button type=\"button\" id=\"sex_male\" class=\"pill flex-1\" aria-pressed=\"true\">Male</button>\n          <button type=\"button\" id=\"sex_female\" class=\"pill flex-1\" aria-pressed=\"false\">Female</button>\n        </div>\n      </div>\n\n      <div class=\"mb-5\">\n        <label class=\"lbl\">Units</label>\n        <div class=\"flex gap-2\" role=\"group\" aria-label=\"Units\">\n          <button type=\"button\" id=\"unit_metric\" class=\"pill flex-1\" aria-pressed=\"true\">Metric \u00b7 cm / kg</button>\n          <button type=\"button\" id=\"unit_imperial\" class=\"pill flex-1\" aria-pressed=\"false\">Imperial \u00b7 in / lb</button>\n        </div>\n      </div>\n\n      <div class=\"grid grid-cols-2 gap-4\">\n        <div>\n          <label class=\"lbl\" for=\"in_height\">Height <span class=\"unit-len\">(cm)</span></label>\n          <input id=\"in_height\" class=\"field num\" type=\"number\" inputmode=\"decimal\" min=\"0\" step=\"any\" value=\"178\" placeholder=\"178\">\n        </div>\n        <div>\n          <label class=\"lbl\" for=\"in_weight\">Weight <span class=\"unit-mass\">(kg)</span></label>\n          <input id=\"in_weight\" class=\"field num\" type=\"number\" inputmode=\"decimal\" min=\"0\" step=\"any\" value=\"78\" placeholder=\"78\">\n        </div>\n        <div>\n          <label class=\"lbl\" for=\"in_age\">Age <span>(years)</span></label>\n          <input id=\"in_age\" class=\"field num\" type=\"number\" inputmode=\"numeric\" min=\"0\" step=\"1\" value=\"32\" placeholder=\"32\">\n        </div>\n        <div>\n          <label class=\"lbl\" for=\"in_neck\">Neck <span class=\"unit-len\">(cm)</span></label>\n          <input id=\"in_neck\" class=\"field num\" type=\"number\" inputmode=\"decimal\" min=\"0\" step=\"any\" value=\"39\" placeholder=\"39\">\n        </div>\n        <div>\n          <label class=\"lbl\" for=\"in_waist\">Waist <span class=\"unit-len\">(cm)</span></label>\n          <input id=\"in_waist\" class=\"field num\" type=\"number\" inputmode=\"decimal\" min=\"0\" step=\"any\" value=\"88\" placeholder=\"88\">\n        </div>\n        <div id=\"hip_wrap\">\n          <label class=\"lbl\" for=\"in_hip\">Hip <span class=\"unit-len\">(cm)</span> <span class=\"normal-case tracking-normal\" style=\"color:var(--yellow);\">\u00b7 female</span></label>\n          <input id=\"in_hip\" class=\"field num\" type=\"number\" inputmode=\"decimal\" min=\"0\" step=\"any\" value=\"102\" placeholder=\"102\">\n        </div>\n      </div>\n\n      <div class=\"flex flex-wrap gap-3 mt-6\">\n        <button id=\"btn_calc\" class=\"btn-primary flex-1 min-w-[140px]\">Calculate</button>\n        <button id=\"btn_reset\" class=\"btn-ghost\">Reset</button>\n      </div>\n      <p class=\"text-[11px] mt-3 leading-relaxed\" style=\"color:var(--faint);\">Inputs auto-save in this browser. Nothing is uploaded anywhere \u2014 TapeTrim works fully offline once loaded.</p>\n    </section>\n\n    <!-- ===== RESULTS ===== -->\n    <section class=\"lg:col-span-3 flex flex-col gap-6\" aria-label=\"Results\" aria-live=\"polite\">\n      <div class=\"card-hi p-5 sm:p-7 relative overflow-hidden\">\n        <div class=\"tape-strip-v absolute left-0 top-0 bottom-0\" aria-hidden=\"true\"></div>\n        <div class=\"pl-4\">\n          <div class=\"flex items-start justify-between gap-4 flex-wrap\">\n            <div>\n              <p class=\"kicker mb-1\">US Navy method</p>\n              <div class=\"giant poster num\" style=\"color:var(--yellow);\" id=\"res_bf\">\u2013</div>\n              <p class=\"text-sm font-semibold\" style=\"color:var(--muted);\">estimated body fat</p>\n            </div>\n            <div class=\"text-right\">\n              <span id=\"res_cat\" class=\"inline-block poster uppercase text-sm sm:text-base px-4 py-2 rounded-lg\" style=\"background:var(--yellow); color:#17130E;\">\u2014</span>\n              <p class=\"text-xs mt-2\" style=\"color:var(--faint);\">ACE fitness category</p>\n              <p class=\"text-xs mt-3\" style=\"color:var(--faint);\">BMI</p>\n              <p class=\"poster text-2xl num\" id=\"res_bmi\">\u2013</p>\n            </div>\n          </div>\n\n          <div class=\"grid grid-cols-2 gap-4 mt-6\">\n            <div class=\"diag rounded-xl p-4\">\n              <p class=\"lbl\">Fat mass</p>\n              <p class=\"poster text-3xl sm:text-4xl num\" id=\"res_fat\">\u2013</p>\n              <p class=\"text-xs mt-1\" style=\"color:var(--faint);\" id=\"res_fat_sub\"></p>\n              <div class=\"h-2 rounded-full mt-3 overflow-hidden\" style=\"background:#14100A;\"><div id=\"bar_fat\" class=\"h-full rounded-full\" style=\"width:0%; background:var(--yellow); transition:width .5s;\"></div></div>\n            </div>\n            <div class=\"diag rounded-xl p-4\">\n              <p class=\"lbl\">Lean mass</p>\n              <p class=\"poster text-3xl sm:text-4xl num\" id=\"res_lean\" style=\"color:var(--ink);\">\u2013</p>\n              <p class=\"text-xs mt-1\" style=\"color:var(--faint);\" id=\"res_lean_sub\"></p>\n              <div class=\"h-2 rounded-full mt-3 overflow-hidden\" style=\"background:#14100A;\"><div id=\"bar_lean\" class=\"h-full rounded-full\" style=\"width:0%; background:var(--ok); transition:width .5s;\"></div></div>\n            </div>\n          </div>\n\n          <div class=\"flex flex-wrap gap-3 mt-5\">\n            <button id=\"btn_copy\" class=\"btn-ghost text-xs\">Copy result</button>\n            <span id=\"copy_note\" class=\"text-xs self-center hidden\" style=\"color:var(--ok);\">Copied!</span>\n          </div>\n        </div>\n      </div>\n\n      <!-- ===== METHOD COMPARISON ===== -->\n      <div class=\"card p-5 sm:p-7\">\n        <div class=\"flex items-center justify-between flex-wrap gap-2 mb-1\">\n          <h2 class=\"poster text-xl uppercase\">Method <span style=\"color:var(--yellow);\">face-off</span></h2>\n          <span class=\"text-[11px] uppercase tracking-widest font-bold\" style=\"color:var(--faint);\">Navy vs Deurenberg</span>\n        </div>\n        <p class=\"text-xs mb-5\" style=\"color:var(--faint);\">Two independent estimates of the same body. Agreement within ~3 points is a healthy sign; a big gap usually means unusual muscle mass or measurement slip.</p>\n        <div class=\"grid sm:grid-cols-3 gap-4\">\n          <div class=\"diag rounded-xl p-4 text-center\">\n            <p class=\"lbl\">US Navy (tape)</p>\n            <p class=\"poster text-4xl num\" style=\"color:var(--yellow);\" id=\"cmp_navy\">\u2013</p>\n            <p class=\"text-[11px] mt-1 leading-snug\" style=\"color:var(--faint);\">circumference formula, log-based</p>\n          </div>\n          <div class=\"diag rounded-xl p-4 text-center\">\n            <p class=\"lbl\">Deurenberg (BMI\u00b7age)</p>\n            <p class=\"poster text-4xl num\" style=\"color:var(--ink);\" id=\"cmp_deu\">\u2013</p>\n            <p class=\"text-[11px] mt-1 leading-snug\" style=\"color:var(--faint);\">1.20\u00d7BMI + 0.23\u00d7age \u2212 10.8\u00d7sex \u2212 5.4</p>\n          </div>\n          <div class=\"diag rounded-xl p-4 text-center\">\n            <p class=\"lbl\">Difference</p>\n            <p class=\"poster text-4xl num\" id=\"cmp_delta\">\u2013</p>\n            <p class=\"text-[11px] mt-1 leading-snug\" style=\"color:var(--faint);\" id=\"cmp_delta_note\"></p>\n          </div>\n        </div>\n      </div>\n\n      <!-- ===== CATEGORY SCALE ===== -->\n      <div class=\"card p-5 sm:p-7\">\n        <h2 class=\"poster text-xl uppercase mb-1\">Where you <span style=\"color:var(--yellow);\">land</span></h2>\n        <p class=\"text-xs mb-5\" style=\"color:var(--faint);\" id=\"scale_sub\">ACE body-fat zones \u2014 cutoffs differ by sex.</p>\n        <div class=\"relative\">\n          <div id=\"scale\" class=\"relative flex h-9 rounded-lg overflow-hidden\" style=\"border:1px solid var(--line);\"></div>\n          <div id=\"scale_marker\" class=\"marker\" style=\"left:0%; display:none;\" aria-hidden=\"true\"></div>\n        </div>\n        <div id=\"scale_labels\" class=\"flex mt-2 text-[10px] uppercase tracking-wider font-bold\" style=\"color:var(--faint);\"></div>\n        <p class=\"text-xs mt-3\" style=\"color:var(--muted);\" id=\"scale_note\"></p>\n      </div>\n\n      <!-- ===== GOAL MODE ===== -->\n      <div class=\"card p-5 sm:p-7\">\n        <div class=\"flex items-center justify-between gap-4 mb-1 flex-wrap\">\n          <h2 class=\"poster text-xl uppercase\">Goal <span style=\"color:var(--yellow);\">mode</span></h2>\n          <button id=\"goal_toggle\" class=\"switch\" role=\"switch\" aria-checked=\"false\" aria-label=\"Toggle goal mode\"></button>\n        </div>\n        <p class=\"text-xs mb-5\" style=\"color:var(--faint);\">Pick a target body-fat %. TapeTrim keeps your lean mass fixed and shows the fat you need to drop \u2014 and the scale weight that goes with it.</p>\n        <div id=\"goal_body\" class=\"hidden\">\n          <div class=\"flex flex-col sm:flex-row sm:items-center gap-4\">\n            <div class=\"flex-1\">\n              <label class=\"lbl\" for=\"in_goal\">Target body fat %</label>\n              <input id=\"in_goal\" type=\"range\" min=\"5\" max=\"40\" step=\"0.5\" value=\"18\" class=\"tslider\" aria-label=\"Target body fat percent\">\n            </div>\n            <div class=\"flex items-center gap-2\">\n              <input id=\"in_goal_num\" class=\"field num w-24 text-center\" type=\"number\" min=\"1\" max=\"60\" step=\"0.5\" value=\"18\" aria-label=\"Target body fat percent (number)\">\n              <span class=\"font-bold\" style=\"color:var(--yellow);\">%</span>\n            </div>\n          </div>\n          <div id=\"goal_out\" class=\"grid sm:grid-cols-3 gap-4 mt-5\"></div>\n        </div>\n      </div>\n\n      <!-- ===== HISTORY ===== -->\n      <div class=\"card p-5 sm:p-7\" id=\"hist_wrap\" style=\"display:none;\">\n        <h2 class=\"poster text-xl uppercase mb-1\">Recent <span style=\"color:var(--yellow);\">checks</span></h2>\n        <p class=\"text-xs mb-4\" style=\"color:var(--faint);\">Saved in this browser only. Tap a chip to reload those measurements.</p>\n        <div id=\"hist_list\" class=\"flex flex-wrap gap-2\"></div>\n      </div>\n    </section>\n  </div>\n\n  <!-- ===== TAPE PLACEMENT GUIDE ===== -->\n  <section class=\"mt-10\" aria-label=\"Tape placement guide\">\n    <div class=\"tape-strip rounded-t-xl\"></div>\n    <div class=\"card rounded-t-none p-5 sm:p-8\" style=\"border-top:none;\">\n      <h2 class=\"poster text-2xl sm:text-3xl uppercase mb-2\">Tape <span style=\"color:var(--yellow);\">placement guide</span></h2>\n      <p class=\"text-sm max-w-2xl mb-6\" style=\"color:var(--muted);\">The formula is only as good as the tape work. Stand relaxed, breathe normally, and measure on bare skin \u2014 the tape should touch without denting the skin. Take each reading twice and average.</p>\n      <div class=\"grid sm:grid-cols-3 gap-5\">\n        <div class=\"diag rounded-xl p-5 text-center\">\n          <svg viewBox=\"0 0 140 185\" class=\"w-full h-44 mx-auto\" role=\"img\" aria-label=\"Neck measurement diagram\">\n            <circle cx=\"70\" cy=\"38\" r=\"27\" fill=\"none\" stroke=\"#FAF6EF\" stroke-width=\"3\"/>\n            <path d=\"M56 64 L54 96 Q70 106 86 96 L84 64\" fill=\"none\" stroke=\"#FAF6EF\" stroke-width=\"3\"/>\n            <path d=\"M54 96 Q34 104 28 150 M86 96 Q106 104 112 150\" fill=\"none\" stroke=\"#FAF6EF\" stroke-width=\"3\"/>\n            <line x1=\"46\" y1=\"76\" x2=\"94\" y2=\"76\" stroke=\"#FFD60A\" stroke-width=\"3.5\" stroke-dasharray=\"8 5\"/>\n            <circle cx=\"46\" cy=\"76\" r=\"3.5\" fill=\"#FFD60A\"/><circle cx=\"94\" cy=\"76\" r=\"3.5\" fill=\"#FFD60A\"/>\n            <text x=\"70\" y=\"178\" text-anchor=\"middle\" fill=\"#8F8471\" font-size=\"10\">keep tape level</text>\n          </svg>\n          <h3 class=\"poster uppercase text-base mt-3\" style=\"color:var(--yellow);\">Neck</h3>\n          <p class=\"text-xs mt-2 leading-relaxed\" style=\"color:var(--muted);\">Just below the Adam's apple, at the base of the neck. Shoulders relaxed, tape horizontal and snug \u2014 don't choke yourself. Look straight ahead.</p>\n        </div>\n        <div class=\"diag rounded-xl p-5 text-center\">\n          <svg viewBox=\"0 0 140 185\" class=\"w-full h-44 mx-auto\" role=\"img\" aria-label=\"Waist measurement diagram\">\n            <path d=\"M45 18 Q70 10 95 18 L90 70 Q88 95 92 120 L86 168 M45 18 L50 70 Q52 95 48 120 L54 168\" fill=\"none\" stroke=\"#FAF6EF\" stroke-width=\"3\"/>\n            <circle cx=\"70\" cy=\"95\" r=\"3\" fill=\"#FFD60A\"/>\n            <line x1=\"42\" y1=\"95\" x2=\"98\" y2=\"95\" stroke=\"#FFD60A\" stroke-width=\"3.5\" stroke-dasharray=\"8 5\"/>\n            <circle cx=\"42\" cy=\"95\" r=\"3.5\" fill=\"#FFD60A\"/><circle cx=\"98\" cy=\"95\" r=\"3.5\" fill=\"#FFD60A\"/>\n            <text x=\"70\" y=\"178\" text-anchor=\"middle\" fill=\"#8F8471\" font-size=\"10\">exhale normally</text>\n          </svg>\n          <h3 class=\"poster uppercase text-base mt-3\" style=\"color:var(--yellow);\">Waist</h3>\n          <p class=\"text-xs mt-2 leading-relaxed\" style=\"color:var(--muted);\"><strong style=\"color:var(--ink);\">Men:</strong> at the navel. <strong style=\"color:var(--ink);\">Women:</strong> the narrowest point of the torso. Exhale normally first \u2014 don't suck in, don't push out.</p>\n        </div>\n        <div class=\"diag rounded-xl p-5 text-center\">\n          <svg viewBox=\"0 0 140 185\" class=\"w-full h-44 mx-auto\" role=\"img\" aria-label=\"Hip measurement diagram\">\n            <path d=\"M52 30 Q70 24 88 30 L94 90 Q100 130 96 165 M52 30 L46 90 Q40 130 44 165\" fill=\"none\" stroke=\"#FAF6EF\" stroke-width=\"3\"/>\n            <line x1=\"36\" y1=\"118\" x2=\"104\" y2=\"118\" stroke=\"#FFD60A\" stroke-width=\"3.5\" stroke-dasharray=\"8 5\"/>\n            <circle cx=\"36\" cy=\"118\" r=\"3.5\" fill=\"#FFD60A\"/><circle cx=\"104\" cy=\"118\" r=\"3.5\" fill=\"#FFD60A\"/>\n            <text x=\"70\" y=\"178\" text-anchor=\"middle\" fill=\"#8F8471\" font-size=\"10\">feet together</text>\n          </svg>\n          <h3 class=\"poster uppercase text-base mt-3\" style=\"color:var(--yellow);\">Hip <span class=\"text-xs\" style=\"color:var(--faint);\">\u00b7 women only</span></h3>\n          <p class=\"text-xs mt-2 leading-relaxed\" style=\"color:var(--muted);\">Feet together, around the widest part of the hips and glutes. Keep the tape level all the way round \u2014 use a mirror to check the back.</p>\n        </div>\n      </div>\n    </div>\n    <div class=\"tape-strip rounded-b-xl\"></div>\n  </section>\n</main>\n\n<!-- ============ BOTTOM AD ============ -->\n<div class=\"no-print mx-auto max-w-6xl px-4 sm:px-6 pb-4\" role=\"complementary\" aria-label=\"Advertisement\">\n  <div class=\"mx-auto text-center\" style=\"max-width:728px\">\n    <span class=\"block text-[10px] tracking-[0.18em] uppercase text-slate-400 mb-1.5\">Advertisement</span>\n    <div class=\"flex justify-center overflow-hidden\">\n      <script async src=\"https://js.wpadmngr.com/static/adManager.js\" data-admpid=\"464498\"></script>\n    </div>\n  </div>\n</div>\n\n<!-- ============ SEO ARTICLE ============ -->\n<section class=\"mx-auto max-w-6xl px-4 sm:px-6 pb-4\">\n  <article id=\"seo-article\" class=\"card p-6 sm:p-10\">\n    <p class=\"kicker mb-3\">The full guide</p>\n    <h2 class=\"poster text-3xl sm:text-4xl uppercase mb-6\">Body fat, the <span style=\"color:var(--yellow);\">Navy method</span>, and how to actually measure yourself</h2>\n\n    <p class=\"dropcap text-sm sm:text-base leading-relaxed mb-5\" style=\"color:var(--muted);\">Your bathroom scale tells you how much you weigh, but it cannot tell you what that weight is made of. Two people can stand at 80 kilograms side by side \u2014 one carrying a soft midsection, the other carrying dense muscle \u2014 and the scale will report the same number for both. Body fat percentage is the number that separates those two stories: it is the share of your total body weight made up of fat tissue, and it is one of the most useful single indicators of fitness, health risk, and progress. The trouble is that measuring it accurately has traditionally meant expensive equipment. That is where the US Navy method comes in. Developed in the 1980s at the Naval Health Research Center by researchers Hodgdon and Beckett, it estimates body fat from a few circumference measurements taken with an ordinary tape measure \u2014 no calipers, no water tanks, no X-ray scanners. It was designed to assess the fitness of thousands of service members quickly and cheaply, and it has since become one of the most widely used field methods in the world. TapeTrim puts both the original Navy formula and an independent cross-check formula in your browser, so you can get a serious estimate with nothing more than a soft measuring tape and five minutes.</p>\n\n    <h3 class=\"poster text-xl uppercase mt-8 mb-3\" style=\"color:var(--yellow);\">How the Navy formula works</h3>\n    <p class=\"text-sm sm:text-base leading-relaxed mb-4\" style=\"color:var(--muted);\">The insight behind the Navy method is that body fat is not distributed randomly. In large population studies, the ratio of waist circumference to neck circumference \u2014 scaled against height \u2014 predicts total body fat remarkably well. The neck measurement is the clever part: it acts as a proxy for upper-body lean mass. A weightlifter with a thick neck and a moderate waist will register a lower body fat percentage than someone with the same waist but a thin neck, because the formula reads the thick neck as evidence of muscle rather than fat. This is why the Navy method outperforms simple waist-only rules for athletic builds.</p>\n    <p class=\"text-sm sm:text-base leading-relaxed mb-4\" style=\"color:var(--muted);\">For men, the formula is: body fat % = 86.010 \u00d7 log\u2081\u2080(waist \u2212 neck) \u2212 70.041 \u00d7 log\u2081\u2080(height) + 36.76. For women, it is: body fat % = 163.205 \u00d7 log\u2081\u2080(waist + hip \u2212 neck) \u2212 97.684 \u00d7 log\u2081\u2080(height) \u2212 78.387, with all measurements in inches. Notice the logarithms: the relationship between tape measurements and body fat is not linear, so the formula compresses the numbers with base-10 logs before combining them. Women's formula adds a hip measurement and uses entirely different constants, reflecting both a higher baseline of essential fat and genuinely different fat-distribution patterns. TapeTrim converts metric inputs to inches internally before applying these exact equations, so you can measure in centimeters and still get the original validated result.</p>\n\n    <h3 class=\"poster text-xl uppercase mt-8 mb-3\" style=\"color:var(--yellow);\">Measuring like the protocol demands</h3>\n    <p class=\"text-sm sm:text-base leading-relaxed mb-4\" style=\"color:var(--muted);\">Here is the uncomfortable truth about the Navy method: your technique moves the answer more than the formula does. A two-centimeter slip on the waist measurement can shift your result by one to two percentage points \u2014 more than a month of disciplined training might. So treat the measurement session like a small ritual. Measure in the morning, before eating, after using the bathroom, and on bare skin: clothing adds bulk that the formula cannot see through. Stand upright and relaxed, breathe normally, and take every reading at the end of a normal exhale \u2014 never while holding your breath or sucking in your stomach. The tape should be snug enough to touch the skin all the way around without leaving a dent. Take each measurement two or three times and use the average; if your readings disagree by more than a centimeter, keep practicing until they converge.</p>\n    <p class=\"text-sm sm:text-base leading-relaxed mb-4\" style=\"color:var(--muted);\">The landmarks matter. For the neck, wrap the tape just below the Adam's apple at the base of the neck, keeping it horizontal while you look straight ahead \u2014 tilting your head up or down changes the reading. For the waist, men measure at the level of the navel; women measure at the narrowest point of the torso, usually a few centimeters above the navel. For the hip (women only), stand with your feet together and wrap the tape around the widest part of the hips and glutes, checking in a mirror that the tape sits level across your back. Height should be measured standing tall without shoes. Write every number down immediately; memory is a worse tape measure than the tape itself.</p>\n\n    <h3 class=\"poster text-xl uppercase mt-8 mb-3\" style=\"color:var(--yellow);\">How accurate is it, really?</h3>\n    <p class=\"text-sm sm:text-base leading-relaxed mb-4\" style=\"color:var(--muted);\">Validated against hydrostatic (underwater) weighing \u2014 the laboratory reference the Navy used \u2014 the method typically lands within three to four percentage points of the true value for average adults. That is honest accuracy: good enough to track change over months, too coarse to treat a single reading as gospel. It is less reliable at the extremes \u2014 very lean athletes, very muscular lifters, and people with obesity can all see larger errors, because their bodies break the population averages the formula was fitted on. Bloating, a big meal, or measuring at different times of day can all add noise that has nothing to do with fat.</p>\n    <p class=\"text-sm sm:text-base leading-relaxed mb-4\" style=\"color:var(--muted);\">This is exactly why TapeTrim shows the Deurenberg estimate beside the Navy result. The Deurenberg formula \u2014 body fat % = 1.20 \u00d7 BMI + 0.23 \u00d7 age \u2212 10.8 \u00d7 sex \u2212 5.4, where sex is 1 for men and 0 for women \u2014 is a completely independent population estimate built from BMI, age, and sex rather than tape measurements. If the Navy and Deurenberg numbers agree within about three points, you can trust the neighborhood your result lives in. If they disagree sharply, the cause is usually informative: a big gap with a high Deurenberg number often flags heavy muscle mass confusing the BMI side, while a gap with a high Navy number usually means a tape reading drifted. Few free calculators show both methods side by side; the comparison turns one fragile number into a small, self-checking system.</p>\n\n    <h3 class=\"poster text-xl uppercase mt-8 mb-3\" style=\"color:var(--yellow);\">Reading your category</h3>\n    <p class=\"text-sm sm:text-base leading-relaxed mb-4\" style=\"color:var(--muted);\">The American Council on Exercise publishes the most widely cited body-fat zones for adults. For men: essential fat 2\u20135%, athletes 6\u201313%, fitness 14\u201317%, average 18\u201324%, and obese at 25% and above. For women: essential fat 10\u201313%, athletes 14\u201320%, fitness 21\u201324%, average 25\u201331%, and obese at 32% and above. Essential fat is the baseline your body needs to function \u2014 it cushions organs, regulates hormones, and in women supports reproduction \u2014 which is why the female scale starts roughly ten points higher. Dropping near or below the essential range is dangerous, not admirable: it is associated with hormonal disruption, weakened immunity, and in women the loss of menstrual cycles.</p>\n    <p class=\"text-sm sm:text-base leading-relaxed mb-4\" style=\"color:var(--muted);\">For most people, the fitness-to-average band is the meaningful target zone \u2014 the range associated with the lowest long-term health risk and the best everyday energy. But context matters. A 55-year-old at 22% is in a different situation than a 25-year-old at 22%, because healthy body fat drifts upward slightly with age. Endurance athletes live happily in the athletes band; powerlifters may sit higher while being extraordinarily healthy by every other metric. Treat the category as a compass, not a verdict: what matters most is the direction your number moves over time under consistent measuring conditions.</p>\n\n    <h3 class=\"poster text-xl uppercase mt-8 mb-3\" style=\"color:var(--yellow);\">Setting a goal and tracking it</h3>\n    <p class=\"text-sm sm:text-base leading-relaxed mb-4\" style=\"color:var(--muted);\">This is where most people misuse body-fat math. Suppose you weigh 85 kilograms at 28% body fat. Your fat mass is about 23.8 kg and your lean mass about 61.2 kg. If you want to reach 20% body fat while keeping your muscle \u2014 and you should want to keep your muscle \u2014 the target weight is not 85 minus some guess: it is your lean mass divided by one minus the target percentage, or 61.2 \u00f7 0.80 \u2248 76.5 kg. That means roughly 8.5 kg of pure fat to lose. TapeTrim's goal mode does exactly this calculation, because the common shortcut of \"lose X% of your weight\" quietly assumes you will lose muscle too, which makes every diet look easier than it is.</p>\n    <p class=\"text-sm sm:text-base leading-relaxed mb-4\" style=\"color:var(--muted);\">Track no more than every two to four weeks. Daily and weekly tape readings mostly measure water, glycogen, gut contents, and your own inconsistency \u2014 real fat change is slower and quieter than that. A sustainable pace is roughly half to one percent of body weight per week, with strength training and adequate protein protecting the lean mass your goal math depends on. If your body-fat percentage stalls while your waist shrinks and your lifts climb, trust the trend: you are likely trading fat for muscle, which is the best possible outcome and one the scale will never show you.</p>\n\n    <h3 class=\"poster text-xl uppercase mt-8 mb-3\" style=\"color:var(--yellow);\">Common mistakes that skew the number</h3>\n    <p class=\"text-sm sm:text-base leading-relaxed mb-4\" style=\"color:var(--muted);\">The classic errors are all technique, not math. Measuring over clothes. Measuring after a workout when muscles are pumped, or after a meal when the waist is distended. Pulling the tape tight enough to compress the skin, which can shave a full point off your reading and flatter you into complacency. Measuring the waist at a different height each time \u2014 the navel for men is a fixed landmark, use it exactly. Comparing a morning fasted reading with an evening reading and concluding your diet failed. And the most human error of all: rounding numbers in the flattering direction. The tape does not care about your feelings, and the formula works best when you let it be blunt.</p>\n    <p class=\"text-sm sm:text-base leading-relaxed mb-4\" style=\"color:var(--muted);\">There are also people for whom the Navy method is simply the wrong tool. It was validated on adults, so it should not be applied to children or teenagers, whose proportions are still changing. Pregnant women should not use it. People with significant edema, unusual fat distribution from medical conditions, or elite-level muscle mass will get numbers the formula was never designed to produce \u2014 for them, a DEXA scan or a trained professional with calipers is the honest route. Everyone else gets a method that costs nothing, takes five minutes, and \u2014 measured carefully and compared across its two formulas \u2014 tells a story your scale never could.</p>\n\n    <h3 class=\"poster text-xl uppercase mt-8 mb-3\" style=\"color:var(--yellow);\">The bottom line</h3>\n    <p class=\"text-sm sm:text-base leading-relaxed mb-2\" style=\"color:var(--muted);\">Body fat percentage turns the vague goal of \"getting in shape\" into something you can measure, target, and track. The US Navy method gives you a validated estimate with a tape measure; the Deurenberg cross-check keeps that estimate honest; the goal math turns your target into kilograms of fat to lose rather than wishful thinking. Measure carefully, measure consistently, and let the trend \u2014 not any single reading \u2014 tell you whether your training and nutrition are working. That is what the tape is for.</p>\n    <p class=\"text-xs mt-6 pt-4\" style=\"color:var(--faint); border-top:1px solid var(--line);\">Educational estimates only \u2014 not medical advice. If you have a health condition or are pursuing an aggressive target, consult a qualified professional.</p>\n  </article>\n</section>\n\n<!-- ============ FAQs ============ -->\n<section class=\"mx-auto max-w-6xl px-4 sm:px-6 py-8\">\n  <div class=\"max-w-3xl\">\n    <p class=\"kicker mb-2\">Questions</p>\n    <h2 class=\"poster text-3xl sm:text-4xl uppercase mb-6\">Body fat <span style=\"color:var(--yellow);\">FAQs</span></h2>\n    <div class=\"space-y-3\" id=\"faq_list\">\n      <div class=\"faq-item\">\n        <button class=\"faq-q w-full flex items-center justify-between gap-4 text-left p-4 sm:p-5 font-semibold\" aria-expanded=\"false\">\n          <span>What is the US Navy body fat formula?</span>\n          <svg class=\"faq-chev shrink-0\" width=\"18\" height=\"18\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"#FFD60A\" stroke-width=\"2.5\"><path d=\"M6 9l6 6 6-6\"/></svg>\n        </button>\n        <div class=\"faq-a\"><p class=\"px-4 sm:px-5 pb-5 text-sm leading-relaxed\" style=\"color:var(--muted);\">Developed by Hodgdon and Beckett in 1984, the Navy formula estimates body fat from tape measurements using base-10 logarithms. Men: 86.010 \u00d7 log\u2081\u2080(waist \u2212 neck) \u2212 70.041 \u00d7 log\u2081\u2080(height) + 36.76. Women: 163.205 \u00d7 log\u2081\u2080(waist + hip \u2212 neck) \u2212 97.684 \u00d7 log\u2081\u2080(height) \u2212 78.387, with all measurements in inches. The neck term corrects for upper-body muscle, which is why the method handles athletic builds better than waist-only estimates.</p></div>\n      </div>\n      <div class=\"faq-item\">\n        <button class=\"faq-q w-full flex items-center justify-between gap-4 text-left p-4 sm:p-5 font-semibold\" aria-expanded=\"false\">\n          <span>How do I measure my neck, waist, and hip correctly?</span>\n          <svg class=\"faq-chev shrink-0\" width=\"18\" height=\"18\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"#FFD60A\" stroke-width=\"2.5\"><path d=\"M6 9l6 6 6-6\"/></svg>\n        </button>\n        <div class=\"faq-a\"><p class=\"px-4 sm:px-5 pb-5 text-sm leading-relaxed\" style=\"color:var(--muted);\">Neck: just below the Adam's apple, tape horizontal, looking straight ahead. Waist: men at the navel, women at the narrowest point of the torso, measured after a normal exhale without sucking in. Hip (women only): feet together, around the widest part of the hips and glutes. Use a soft non-stretch tape on bare skin, keep it snug but not denting the skin, and average two or three readings. The illustrated placement guide above shows each landmark.</p></div>\n      </div>\n      <div class=\"faq-item\">\n        <button class=\"faq-q w-full flex items-center justify-between gap-4 text-left p-4 sm:p-5 font-semibold\" aria-expanded=\"false\">\n          <span>How accurate is the Navy method compared to a DEXA scan?</span>\n          <svg class=\"faq-chev shrink-0\" width=\"18\" height=\"18\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"#FFD60A\" stroke-width=\"2.5\"><path d=\"M6 9l6 6 6-6\"/></svg>\n        </button>\n        <div class=\"faq-a\"><p class=\"px-4 sm:px-5 pb-5 text-sm leading-relaxed\" style=\"color:var(--muted);\">For average adults the Navy method typically lands within 3\u20134 percentage points of hydrostatic weighing, the laboratory reference it was validated against \u2014 DEXA scans are generally more precise but cost far more and are harder to access. Accuracy drops for very lean, very muscular, or obese individuals, and measurement technique matters more than the formula: a 2 cm waist error can move the result by 1\u20132 points. It is best used to track trends over time under consistent conditions rather than as a single exact number.</p></div>\n      </div>\n      <div class=\"faq-item\">\n        <button class=\"faq-q w-full flex items-center justify-between gap-4 text-left p-4 sm:p-5 font-semibold\" aria-expanded=\"false\">\n          <span>What are the healthy body fat ranges for men and women?</span>\n          <svg class=\"faq-chev shrink-0\" width=\"18\" height=\"18\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"#FFD60A\" stroke-width=\"2.5\"><path d=\"M6 9l6 6 6-6\"/></svg>\n        </button>\n        <div class=\"faq-a\"><p class=\"px-4 sm:px-5 pb-5 text-sm leading-relaxed\" style=\"color:var(--muted);\">Per the American Council on Exercise: men \u2014 essential 2\u20135%, athletes 6\u201313%, fitness 14\u201317%, average 18\u201324%, obese 25%+. Women \u2014 essential 10\u201313%, athletes 14\u201320%, fitness 21\u201324%, average 25\u201331%, obese 32%+. The fitness-to-average band is the meaningful target for most people. Ranges drift slightly upward with age, and athletes or very muscular individuals should interpret categories alongside other health markers.</p></div>\n      </div>\n      <div class=\"faq-item\">\n        <button class=\"faq-q w-full flex items-center justify-between gap-4 text-left p-4 sm:p-5 font-semibold\" aria-expanded=\"false\">\n          <span>Why is the Deurenberg estimate shown next to the Navy result?</span>\n          <svg class=\"faq-chev shrink-0\" width=\"18\" height=\"18\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"#FFD60A\" stroke-width=\"2.5\"><path d=\"M6 9l6 6 6-6\"/></svg>\n        </button>\n        <div class=\"faq-a\"><p class=\"px-4 sm:px-5 pb-5 text-sm leading-relaxed\" style=\"color:var(--muted);\">The Deurenberg formula (1.20 \u00d7 BMI + 0.23 \u00d7 age \u2212 10.8 \u00d7 sex \u2212 5.4) is a fully independent population estimate built from BMI, age, and sex instead of tape measurements. Showing both turns one fragile number into a self-checking system: agreement within about 3 points means you can trust the neighborhood; a large gap usually flags either heavy muscle mass confusing the BMI side or a tape reading that drifted on the Navy side. Very few free calculators offer this comparison.</p></div>\n      </div>\n      <div class=\"faq-item\">\n        <button class=\"faq-q w-full flex items-center justify-between gap-4 text-left p-4 sm:p-5 font-semibold\" aria-expanded=\"false\">\n          <span>How often should I re-measure to track fat loss?</span>\n          <svg class=\"faq-chev shrink-0\" width=\"18\" height=\"18\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"#FFD60A\" stroke-width=\"2.5\"><path d=\"M6 9l6 6 6-6\"/></svg>\n        </button>\n        <div class=\"faq-a\"><p class=\"px-4 sm:px-5 pb-5 text-sm leading-relaxed\" style=\"color:var(--muted);\">Every two to four weeks, under identical conditions \u2014 morning, fasted, same tape landmarks. Daily or weekly readings mostly reflect water, glycogen, gut contents, and technique noise rather than real fat change. A sustainable pace is about 0.5\u20131% of body weight per week with strength training and adequate protein to protect lean mass. If your percentage stalls while your waist shrinks and strength climbs, you are likely trading fat for muscle \u2014 trust the trend, not any single reading.</p></div>\n      </div>\n    </div>\n  </div>\n</section>\n\n<script type=\"application/ld+json\">\n{\n  \"@context\": \"https://schema.org\",\n  \"@type\": \"FAQPage\",\n  \"mainEntity\": [\n    { \"@type\": \"Question\", \"name\": \"What is the US Navy body fat formula?\", \"acceptedAnswer\": { \"@type\": \"Answer\", \"text\": \"The Navy formula estimates body fat from tape measurements using base-10 logarithms. Men: 86.010 x log10(waist - neck) - 70.041 x log10(height) + 36.76. Women: 163.205 x log10(waist + hip - neck) - 97.684 x log10(height) - 78.387, all measurements in inches.\" } },\n    { \"@type\": \"Question\", \"name\": \"How do I measure my neck, waist, and hip correctly?\", \"acceptedAnswer\": { \"@type\": \"Answer\", \"text\": \"Neck: just below the Adam's apple, tape horizontal. Waist: men at the navel, women at the narrowest point of the torso, after a normal exhale. Hip (women only): feet together, around the widest part of the hips. Use a soft tape on bare skin, snug but not compressing, and average two or three readings.\" } },\n    { \"@type\": \"Question\", \"name\": \"How accurate is the Navy method compared to a DEXA scan?\", \"acceptedAnswer\": { \"@type\": \"Answer\", \"text\": \"For average adults it typically lands within 3-4 percentage points of laboratory reference methods. Accuracy drops for very lean, very muscular, or obese individuals, and technique matters more than the formula. It is best for tracking trends over time under consistent conditions.\" } },\n    { \"@type\": \"Question\", \"name\": \"What are the healthy body fat ranges for men and women?\", \"acceptedAnswer\": { \"@type\": \"Answer\", \"text\": \"Per the American Council on Exercise: men - essential 2-5%, athletes 6-13%, fitness 14-17%, average 18-24%, obese 25%+. Women - essential 10-13%, athletes 14-20%, fitness 21-24%, average 25-31%, obese 32%+.\" } },\n    { \"@type\": \"Question\", \"name\": \"Why is the Deurenberg estimate shown next to the Navy result?\", \"acceptedAnswer\": { \"@type\": \"Answer\", \"text\": \"The Deurenberg formula (1.20 x BMI + 0.23 x age - 10.8 x sex - 5.4) is an independent estimate from BMI, age, and sex. Agreement within about 3 points with the Navy result increases confidence; a large gap usually flags heavy muscle mass or a tape measurement that drifted.\" } },\n    { \"@type\": \"Question\", \"name\": \"How often should I re-measure to track fat loss?\", \"acceptedAnswer\": { \"@type\": \"Answer\", \"text\": \"Every two to four weeks under identical conditions - morning, fasted, same tape landmarks. A sustainable pace is about 0.5-1% of body weight per week with strength training and adequate protein to protect lean mass.\" } }\n  ]\n}\n</script>\n\n<!-- ============ FOOTER ============ -->\n<footer class=\"mt-6 border-t\" style=\"border-color:var(--line);\">\n  <div class=\"mx-auto max-w-6xl px-4 sm:px-6 py-8 flex flex-col sm:flex-row items-center justify-between gap-4\">\n    <p class=\"poster text-lg tracking-tight\">Tape<span style=\"color:var(--yellow);\">Trim</span></p>\n    <p class=\"text-xs text-center\" style=\"color:var(--faint);\">Free US Navy body fat calculator. Educational estimates only \u2014 not medical advice.</p>\n    <a href=\"https://fixoraa.tech\" class=\"text-sm font-semibold hover:underline\" style=\"color:var(--yellow);\">More Tools</a>\n  </div>\n<p class=\"fx-credit\" style=\"text-align:center;font-size:12.5px;opacity:.62;margin:10px auto 2px;letter-spacing:.01em\">Made by <a href=\"https://fixoraa.tech\" target=\"_blank\" rel=\"noopener\" style=\"color:inherit;font-weight:700;text-decoration:underline;text-underline-offset:2px\">Fixoraa</a></p>\n</footer>\n\n<script>\n/*__PURE_START__*/\n'use strict';\n/* ===== TapeTrim pure calculation logic \u2014 no DOM access. Safe to run in Node. ===== */\n\nvar TT_CM_PER_IN = 2.54;\nvar TT_KG_PER_LB = 0.45359237;\n\nfunction ttToNum(v, fallback) {\n  var n = (typeof v === 'string' && v.trim() === '') ? NaN : Number(v);\n  return Number.isFinite(n) ? n : fallback;\n}\nfunction ttCmToIn(cm) { cm = ttToNum(cm, NaN); return Number.isFinite(cm) ? cm / TT_CM_PER_IN : NaN; }\nfunction ttInToCm(i) { i = ttToNum(i, NaN); return Number.isFinite(i) ? i * TT_CM_PER_IN : NaN; }\nfunction ttKgToLb(kg) { kg = ttToNum(kg, NaN); return Number.isFinite(kg) ? kg / TT_KG_PER_LB : NaN; }\nfunction ttLbToKg(lb) { lb = ttToNum(lb, NaN); return Number.isFinite(lb) ? lb * TT_KG_PER_LB : NaN; }\n\n/* US Navy body-fat formula. All lengths in inches. Returns BF% or NaN. */\nfunction ttNavy(sex, hIn, neckIn, waistIn, hipIn) {\n  hIn = ttToNum(hIn, NaN); neckIn = ttToNum(neckIn, NaN);\n  waistIn = ttToNum(waistIn, NaN); hipIn = ttToNum(hipIn, NaN);\n  if (!(hIn > 0 && neckIn > 0 && waistIn > 0)) return NaN;\n  var l10 = Math.log10;\n  if (sex === 'male') {\n    var d = waistIn - neckIn;\n    if (!(d > 0)) return NaN;\n    return 86.010 * l10(d) - 70.041 * l10(hIn) + 36.76;\n  }\n  if (sex === 'female') {\n    if (!(hipIn > 0)) return NaN;\n    var d2 = waistIn + hipIn - neckIn;\n    if (!(d2 > 0)) return NaN;\n    return 163.205 * l10(d2) - 97.684 * l10(hIn) - 78.387;\n  }\n  return NaN;\n}\n\n/* Deurenberg BMI-based estimate: 1.20*BMI + 0.23*age - 10.8*sex - 5.4 (sex: male=1, female=0) */\nfunction ttDeurenberg(bmi, age, sex) {\n  bmi = ttToNum(bmi, NaN); age = ttToNum(age, NaN);\n  if (!(bmi > 0) || !(age >= 0)) return NaN;\n  if (sex !== 'male' && sex !== 'female') return NaN;\n  return 1.20 * bmi + 0.23 * age - 10.8 * (sex === 'male' ? 1 : 0) - 5.4;\n}\n\nfunction ttBmi(weightKg, heightCm) {\n  weightKg = ttToNum(weightKg, NaN); heightCm = ttToNum(heightCm, NaN);\n  if (!(weightKg > 0 && heightCm > 0)) return NaN;\n  var m = heightCm / 100;\n  return weightKg / (m * m);\n}\n\n/* ACE body-fat zones, contiguous. Scale runs 0-45 for the visual bar. */\nvar TT_ZONES = {\n  male: [\n    { name: 'Essential', min: 0, max: 6 },\n    { name: 'Athletes', min: 6, max: 14 },\n    { name: 'Fitness', min: 14, max: 18 },\n    { name: 'Average', min: 18, max: 25 },\n    { name: 'Obese', min: 25, max: 45 }\n  ],\n  female: [\n    { name: 'Essential', min: 0, max: 14 },\n    { name: 'Athletes', min: 14, max: 21 },\n    { name: 'Fitness', min: 21, max: 25 },\n    { name: 'Average', min: 25, max: 32 },\n    { name: 'Obese', min: 32, max: 45 }\n  ]\n};\n\nfunction ttCategory(sex, bf) {\n  bf = ttToNum(bf, NaN);\n  var zones = TT_ZONES[sex];\n  if (!zones || !(bf >= 0)) return null;\n  for (var i = 0; i < zones.length; i++) {\n    var z = zones[i];\n    if (bf >= z.min && (bf < z.max || i === zones.length - 1)) return z.name;\n  }\n  return null;\n}\n\n/* Split weight into fat and lean mass at a given body-fat %. */\nfunction ttMass(weightKg, bf) {\n  weightKg = ttToNum(weightKg, NaN); bf = ttToNum(bf, NaN);\n  if (!(weightKg > 0) || !(bf >= 0) || !(bf < 100)) return { fatKg: NaN, leanKg: NaN };\n  var fatKg = weightKg * bf / 100;\n  return { fatKg: fatKg, leanKg: weightKg - fatKg };\n}\n\n/*\n * Goal mode: keep lean mass fixed, solve for the weight at target BF%.\n * Returns { ok, targetWeightKg, fatToLoseKg, leanKg, status } where status is\n * 'lose' | 'gain' | 'same'. fatToLoseKg is positive when fat must be lost.\n */\nfunction ttGoal(weightKg, bf, target) {\n  weightKg = ttToNum(weightKg, NaN); bf = ttToNum(bf, NaN); target = ttToNum(target, NaN);\n  var bad = { ok: false, targetWeightKg: NaN, fatToLoseKg: NaN, leanKg: NaN, status: 'invalid' };\n  if (!(weightKg > 0) || !(bf > 0) || !(bf < 100) || !(target > 0) || !(target < 100)) return bad;\n  var leanKg = weightKg * (1 - bf / 100);\n  if (!(leanKg > 0)) return bad;\n  var targetWeightKg = leanKg / (1 - target / 100);\n  var fatToLoseKg = weightKg - targetWeightKg;\n  var status = fatToLoseKg > 0.05 ? 'lose' : (fatToLoseKg < -0.05 ? 'gain' : 'same');\n  return { ok: true, targetWeightKg: targetWeightKg, fatToLoseKg: fatToLoseKg, leanKg: leanKg, status: status };\n}\n\n/*\n * Validate raw display-unit inputs. d = {height, weight, age, neck, waist, hip}.\n * Returns an array of friendly error strings (empty = valid).\n */\nfunction ttValidate(sex, unit, d) {\n  var errs = [];\n  var isMetric = unit === 'metric';\n  var height = ttToNum(d.height, NaN), weight = ttToNum(d.weight, NaN), age = ttToNum(d.age, NaN);\n  var neck = ttToNum(d.neck, NaN), waist = ttToNum(d.waist, NaN), hip = ttToNum(d.hip, NaN);\n\n  var hCm = isMetric ? height : ttInToCm(height);\n  var wKg = isMetric ? weight : ttLbToKg(weight);\n  var neckIn = isMetric ? ttCmToIn(neck) : neck;\n  var waistIn = isMetric ? ttCmToIn(waist) : waist;\n  var hipIn = isMetric ? ttCmToIn(hip) : hip;\n\n  if (!(height > 0)) errs.push('Please enter your height.');\n  else if (!(hCm >= 100 && hCm <= 250)) errs.push('Height looks off \u2014 expected 100\u2013250 cm (39\u201398 in).');\n  if (!(weight > 0)) errs.push('Please enter your weight.');\n  else if (!(wKg >= 25 && wKg <= 400)) errs.push('Weight looks off \u2014 expected 25\u2013400 kg (55\u2013880 lb).');\n  if (!(age >= 14)) errs.push('The Navy method is validated for adults \u2014 please enter an age of 14 or older.');\n  else if (!(age <= 100)) errs.push('Age looks off \u2014 please enter 100 or less.');\n  if (!(neck > 0)) errs.push('Please enter your neck measurement.');\n  if (!(waist > 0)) errs.push('Please enter your waist measurement.');\n  if (sex === 'female' && !(hip > 0)) errs.push('Please enter your hip measurement (needed for the female formula).');\n  if (sex !== 'male' && sex !== 'female') errs.push('Please choose male or female.');\n  if (unit !== 'metric' && unit !== 'imperial') errs.push('Please choose metric or imperial units.');\n\n  if (errs.length === 0) {\n    if (sex === 'male' && !(waistIn > neckIn)) errs.push('Waist must be larger than neck \u2014 double-check your tape readings.');\n    if (sex === 'female' && !(waistIn + hipIn > neckIn)) errs.push('Waist + hip must be larger than neck \u2014 double-check your tape readings.');\n  }\n  return errs;\n}\n\n/* Full pipeline: raw display-unit inputs -> validated result object. */\nfunction ttCompute(sex, unit, d) {\n  var errors = ttValidate(sex, unit, d);\n  var isMetric = unit === 'metric';\n  var hCm = isMetric ? ttToNum(d.height, NaN) : ttInToCm(d.height);\n  var wKg = isMetric ? ttToNum(d.weight, NaN) : ttLbToKg(d.weight);\n  var age = ttToNum(d.age, NaN);\n  var hIn = ttCmToIn(hCm);\n  var neckIn = isMetric ? ttCmToIn(d.neck) : ttToNum(d.neck, NaN);\n  var waistIn = isMetric ? ttCmToIn(d.waist) : ttToNum(d.waist, NaN);\n  var hipIn = sex === 'female' ? (isMetric ? ttCmToIn(d.hip) : ttToNum(d.hip, NaN)) : NaN;\n\n  var out = { errors: errors, sex: sex, unit: unit, weightKg: wKg, heightCm: hCm, age: age,\n              navy: NaN, deurenberg: NaN, bmi: NaN, fatKg: NaN, leanKg: NaN,\n              category: null, zones: TT_ZONES[sex] || TT_ZONES.male };\n  if (errors.length > 0) return out;\n  out.navy = ttNavy(sex, hIn, neckIn, waistIn, hipIn);\n  out.bmi = ttBmi(wKg, hCm);\n  out.deurenberg = ttDeurenberg(out.bmi, age, sex);\n  var m = ttMass(wKg, out.navy);\n  out.fatKg = m.fatKg; out.leanKg = m.leanKg;\n  out.category = ttCategory(sex, out.navy);\n  return out;\n}\n\nfunction ttFmt(n, dec) {\n  n = ttToNum(n, NaN);\n  if (!Number.isFinite(n)) return '\u2013';\n  return n.toFixed(dec == null ? 1 : dec);\n}\n/*__PURE_END__*/\n\n/* ================= UI glue (DOM only, not part of pure logic) ================= */\n(function () {\n  'use strict';\n  var STORE = 'tapetrim-v1', HIST = 'tapetrim-hist';\n  var ZONE_COLORS = ['#6E6046', '#A8892F', '#FFD60A', '#E07B39', '#D64541'];\n\n  function $(id) { return document.getElementById(id); }\n  function esc(s) {\n    return String(s).replace(/[&<>\"']/g, function (c) {\n      return { '&': '&amp;', '<': '&lt;', '>': '&gt;', '\"': '&quot;', \"'\": '&#39;' }[c];\n    });\n  }\n\n  var state = { sex: 'male', unit: 'metric', goalOn: false };\n\n  function readInputs() {\n    return {\n      height: $('in_height').value, weight: $('in_weight').value, age: $('in_age').value,\n      neck: $('in_neck').value, waist: $('in_waist').value, hip: $('in_hip').value\n    };\n  }\n  function massUnit() { return state.unit === 'metric' ? 'kg' : 'lb'; }\n  function toMass(kg) { return state.unit === 'metric' ? kg : ttKgToLb(kg); }\n\n  function setPressed(id, on) { $(id).setAttribute('aria-pressed', on ? 'true' : 'false'); }\n\n  function setSex(s) {\n    state.sex = s;\n    setPressed('sex_male', s === 'male');\n    setPressed('sex_female', s === 'female');\n    $('hip_wrap').style.display = s === 'female' ? '' : 'none';\n    var g = $('in_goal'), gn = $('in_goal_num');\n    if (s === 'female') { g.min = 12; gn.min = 8; if (Number(g.value) < 12) { g.value = 24; gn.value = 24; } }\n    else { g.min = 5; gn.min = 5; if (Number(g.value) > 40) { g.value = 18; gn.value = 18; } }\n    recalc();\n  }\n\n  function convertInputs(toUnit) {\n    var fromMetric = state.unit === 'metric';\n    if ((fromMetric && toUnit === 'metric') || (!fromMetric && toUnit === 'imperial')) return;\n    function convLen(v) {\n      var n = ttToNum(v, NaN);\n      if (!Number.isFinite(n)) return v;\n      return (fromMetric ? ttCmToIn(n) : ttInToCm(n)).toFixed(1);\n    }\n    function convMass(v) {\n      var n = ttToNum(v, NaN);\n      if (!Number.isFinite(n)) return v;\n      return (fromMetric ? ttKgToLb(n) : ttLbToKg(n)).toFixed(1);\n    }\n    $('in_height').value = convLen($('in_height').value);\n    $('in_neck').value = convLen($('in_neck').value);\n    $('in_waist').value = convLen($('in_waist').value);\n    $('in_hip').value = convLen($('in_hip').value);\n    $('in_weight').value = convMass($('in_weight').value);\n    state.unit = toUnit;\n    setPressed('unit_metric', toUnit === 'metric');\n    setPressed('unit_imperial', toUnit === 'imperial');\n    var lenU = toUnit === 'metric' ? '(cm)' : '(in)';\n    var massU = toUnit === 'metric' ? '(kg)' : '(lb)';\n    document.querySelectorAll('.unit-len').forEach(function (el) { el.textContent = lenU; });\n    document.querySelectorAll('.unit-mass').forEach(function (el) { el.textContent = massU; });\n    $('in_height').placeholder = toUnit === 'metric' ? '178' : '70';\n    $('in_weight').placeholder = toUnit === 'metric' ? '78' : '172';\n  }\n\n  function showErrors(errs) {\n    var box = $('errors');\n    if (!errs.length) { box.classList.add('hidden'); box.innerHTML = ''; return; }\n    box.classList.remove('hidden');\n    box.innerHTML = '<p class=\"font-bold mb-1\" style=\"color:var(--danger);\">Check your tape readings:</p><ul class=\"list-disc pl-5 space-y-1\">' +\n      errs.map(function (e) { return '<li>' + esc(e) + '</li>'; }).join('') + '</ul>';\n  }\n\n  function renderScale(r) {\n    var host = $('scale'), labels = $('scale_labels');\n    host.innerHTML = ''; labels.innerHTML = '';\n    var total = 45;\n    r.zones.forEach(function (z, i) {\n      var seg = document.createElement('div');\n      seg.className = 'zone-seg';\n      seg.style.width = ((z.max - z.min) / total * 100) + '%';\n      seg.style.background = ZONE_COLORS[i];\n      seg.title = z.name + ': ' + z.min + '\u2013' + (i === r.zones.length - 1 ? z.max + '+' : z.max) + '%';\n      host.appendChild(seg);\n      var lab = document.createElement('div');\n      lab.style.width = ((z.max - z.min) / total * 100) + '%';\n      lab.className = 'px-1 truncate';\n      lab.textContent = z.name;\n      labels.appendChild(lab);\n    });\n    var mk = $('scale_marker');\n    if (Number.isFinite(r.navy)) {\n      var pct = Math.min(100, Math.max(0, r.navy / total * 100));\n      mk.style.left = 'calc(' + pct.toFixed(2) + '% - 1px)';\n      mk.style.display = '';\n    } else { mk.style.display = 'none'; }\n    $('scale_sub').textContent = 'ACE body-fat zones for ' + (r.sex === 'male' ? 'men' : 'women') + ' \u2014 marker shows your Navy result.';\n    if (Number.isFinite(r.navy) && r.category) {\n      var z = r.zones.filter(function (x) { return x.name === r.category; })[0];\n      var note;\n      if (r.category === 'Obese') note = ttFmt(r.navy, 1) + '% sits in the Obese zone \u2014 even a 5-point drop brings measurable health gains.';\n      else if (z) note = ttFmt(r.navy, 1) + '% sits in the ' + r.category + ' zone (' + z.min + '\u2013' + z.max + '% for ' + (r.sex === 'male' ? 'men' : 'women') + ').';\n      else note = '';\n      $('scale_note').textContent = note;\n    } else { $('scale_note').textContent = ''; }\n  }\n\n  function renderGoal(r) {\n    var out = $('goal_out');\n    if (!state.goalOn) return;\n    var target = ttToNum($('in_goal_num').value, NaN);\n    if (!Number.isFinite(r.navy) || !Number.isFinite(target)) {\n      out.innerHTML = '<p class=\"text-sm col-span-3\" style=\"color:var(--faint);\">Calculate a valid result and set a target to see your goal math.</p>';\n      return;\n    }\n    var g = ttGoal(r.weightKg, r.navy, target);\n    if (!g.ok) {\n      out.innerHTML = '<p class=\"text-sm col-span-3\" style=\"color:var(--danger);\">Target must be between 1% and 99%.</p>';\n      return;\n    }\n    var u = massUnit();\n    var headline, sub;\n    if (g.status === 'lose') {\n      headline = 'Lose ' + ttFmt(toMass(g.fatToLoseKg), 1) + ' ' + u;\n      sub = 'of pure fat to reach ' + ttFmt(target, 1) + '%';\n    } else if (g.status === 'gain') {\n      headline = 'Gain ' + ttFmt(toMass(-g.fatToLoseKg), 1) + ' ' + u;\n      sub = 'you are already leaner than ' + ttFmt(target, 1) + '% \u2014 this is the weight at that target';\n    } else {\n      headline = 'On target';\n      sub = 'you are within a hair of ' + ttFmt(target, 1) + '%';\n    }\n    out.innerHTML =\n      '<div class=\"diag rounded-xl p-4 text-center\"><p class=\"lbl\">Fat to shift</p><p class=\"poster text-2xl num\" style=\"color:var(--yellow);\">' + esc(headline) + '</p><p class=\"text-[11px] mt-1\" style=\"color:var(--faint);\">' + esc(sub) + '</p></div>' +\n      '<div class=\"diag rounded-xl p-4 text-center\"><p class=\"lbl\">Target weight</p><p class=\"poster text-2xl num\">' + esc(ttFmt(toMass(g.targetWeightKg), 1)) + ' ' + u + '</p><p class=\"text-[11px] mt-1\" style=\"color:var(--faint);\">at ' + esc(ttFmt(target, 1)) + '% body fat</p></div>' +\n      '<div class=\"diag rounded-xl p-4 text-center\"><p class=\"lbl\">Lean mass protected</p><p class=\"poster text-2xl num\" style=\"color:var(--ok);\">' + esc(ttFmt(toMass(g.leanKg), 1)) + ' ' + u + '</p><p class=\"text-[11px] mt-1\" style=\"color:var(--faint);\">kept constant in this math</p></div>';\n  }\n\n  function saveHistory(r) {\n    if (!Number.isFinite(r.navy)) return;\n    try {\n      var h = JSON.parse(localStorage.getItem(HIST) || '[]');\n      h.unshift({ t: Date.now(), sex: r.sex, unit: r.unit, bf: Math.round(r.navy * 10) / 10,\n                  cat: r.category, d: readInputs() });\n      h = h.slice(0, 5);\n      localStorage.setItem(HIST, JSON.stringify(h));\n      renderHistory();\n    } catch (e) {}\n  }\n\n  function renderHistory() {\n    var wrap = $('hist_wrap'), list = $('hist_list');\n    var h = [];\n    try { h = JSON.parse(localStorage.getItem(HIST) || '[]'); } catch (e) {}\n    if (!h.length) { wrap.style.display = 'none'; return; }\n    wrap.style.display = '';\n    list.innerHTML = '';\n    h.forEach(function (item, idx) {\n      var b = document.createElement('button');\n      b.type = 'button';\n      b.className = 'hist-chip diag rounded-lg px-3 py-2 text-xs font-bold num';\n      var dt = new Date(item.t);\n      b.innerHTML = '<span style=\"color:var(--yellow);\">' + esc(ttFmt(item.bf, 1)) + '%</span> <span style=\"color:var(--faint);\">' +\n        esc(item.cat || '') + ' \u00b7 ' + esc(dt.toLocaleDateString()) + '</span>';\n      b.addEventListener('click', function () { restoreItem(item); });\n      b.dataset.idx = idx;\n      list.appendChild(b);\n    });\n  }\n\n  function restoreItem(item) {\n    setSexSilent(item.sex);\n    if (item.unit !== state.unit) convertInputs(item.unit);\n    $('in_height').value = item.d.height; $('in_weight').value = item.d.weight;\n    $('in_age').value = item.d.age; $('in_neck').value = item.d.neck;\n    $('in_waist').value = item.d.waist; $('in_hip').value = item.d.hip;\n    recalc();\n  }\n  function setSexSilent(s) {\n    state.sex = s;\n    setPressed('sex_male', s === 'male');\n    setPressed('sex_female', s === 'female');\n    $('hip_wrap').style.display = s === 'female' ? '' : 'none';\n  }\n\n  function saveState() {\n    try { localStorage.setItem(STORE, JSON.stringify({ sex: state.sex, unit: state.unit, d: readInputs(), goal: $('in_goal_num').value })); }\n    catch (e) {}\n  }\n  function loadState() {\n    try {\n      var s = JSON.parse(localStorage.getItem(STORE) || 'null');\n      if (!s || !s.d) return false;\n      setSexSilent(s.sex === 'female' ? 'female' : 'male');\n      state.unit = 'metric';\n      setPressed('unit_metric', true); setPressed('unit_imperial', false);\n      $('in_height').value = s.d.height; $('in_weight').value = s.d.weight;\n      $('in_age').value = s.d.age; $('in_neck').value = s.d.neck;\n      $('in_waist').value = s.d.waist; $('in_hip').value = s.d.hip || '';\n      if (s.unit === 'imperial') convertInputs('imperial');\n      if (s.goal) { $('in_goal').value = s.goal; $('in_goal_num').value = s.goal; }\n      return true;\n    } catch (e) { return false; }\n  }\n\n  function recalc() {\n    var r = ttCompute(state.sex, state.unit, readInputs());\n    showErrors(r.errors);\n    var valid = r.errors.length === 0 && Number.isFinite(r.navy);\n    $('res_bf').textContent = valid ? ttFmt(r.navy, 1) + '%' : '\u2013';\n    $('hero_tease').textContent = valid ? ttFmt(r.navy, 1) + '%' : '\u2013%';\n    $('res_bmi').textContent = valid ? ttFmt(r.bmi, 1) : '\u2013';\n    $('res_cat').textContent = valid && r.category ? r.category : '\u2014';\n    var u = massUnit();\n    if (valid) {\n      $('res_fat').textContent = ttFmt(toMass(r.fatKg), 1) + ' ' + u;\n      $('res_lean').textContent = ttFmt(toMass(r.leanKg), 1) + ' ' + u;\n      $('res_fat_sub').textContent = ttFmt(r.navy, 1) + '% of total weight';\n      $('res_lean_sub').textContent = ttFmt(100 - r.navy, 1) + '% of total weight';\n      $('bar_fat').style.width = Math.min(100, r.navy) + '%';\n      $('bar_lean').style.width = Math.min(100, 100 - r.navy) + '%';\n      $('cmp_navy').textContent = ttFmt(r.navy, 1) + '%';\n      $('cmp_deu').textContent = ttFmt(r.deurenberg, 1) + '%';\n      var delta = r.navy - r.deurenberg;\n      var dEl = $('cmp_delta');\n      dEl.textContent = (delta >= 0 ? '+' : '') + ttFmt(delta, 1) + ' pt';\n      dEl.style.color = Math.abs(delta) <= 3 ? 'var(--ok)' : 'var(--danger)';\n      $('cmp_delta_note').textContent = Math.abs(delta) <= 3 ? 'methods agree \u2014 trust the neighborhood' : 'wide gap \u2014 re-check tape readings';\n    } else {\n      $('res_fat').textContent = '\u2013'; $('res_lean').textContent = '\u2013';\n      $('res_fat_sub').textContent = ''; $('res_lean_sub').textContent = '';\n      $('bar_fat').style.width = '0%'; $('bar_lean').style.width = '0%';\n      $('cmp_navy').textContent = '\u2013'; $('cmp_deu').textContent = '\u2013';\n      $('cmp_delta').textContent = '\u2013'; $('cmp_delta').style.color = ''; $('cmp_delta_note').textContent = '';\n    }\n    renderScale(r);\n    renderGoal(r);\n    saveState();\n  }\n\n  function wire() {\n    ['in_height', 'in_weight', 'in_age', 'in_neck', 'in_waist', 'in_hip'].forEach(function (id) {\n      $(id).addEventListener('input', recalc);\n    });\n    $('sex_male').addEventListener('click', function () { setSex('male'); });\n    $('sex_female').addEventListener('click', function () { setSex('female'); });\n    $('unit_metric').addEventListener('click', function () { convertInputs('metric'); recalc(); });\n    $('unit_imperial').addEventListener('click', function () { convertInputs('imperial'); recalc(); });\n    $('btn_calc').addEventListener('click', function () {\n      recalc();\n      var r = ttCompute(state.sex, state.unit, readInputs());\n      if (r.errors.length === 0 && Number.isFinite(r.navy)) saveHistory(r);\n    });\n    $('btn_reset').addEventListener('click', function () {\n      try { localStorage.removeItem(STORE); } catch (e) {}\n      setSexSilent('male');\n      if (state.unit !== 'metric') convertInputs('metric');\n      $('in_height').value = 178; $('in_weight').value = 78; $('in_age').value = 32;\n      $('in_neck').value = 39; $('in_waist').value = 88; $('in_hip').value = 102;\n      recalc();\n    });\n    $('btn_copy').addEventListener('click', function () {\n      var r = ttCompute(state.sex, state.unit, readInputs());\n      if (r.errors.length || !Number.isFinite(r.navy)) return;\n      var u = massUnit();\n      var txt = 'TapeTrim body-fat check: ' + ttFmt(r.navy, 1) + '% (Navy) / ' + ttFmt(r.deurenberg, 1) +\n        '% (Deurenberg), ' + r.category + '. Fat ' + ttFmt(toMass(r.fatKg), 1) + u + ', lean ' +\n        ttFmt(toMass(r.leanKg), 1) + u + ', BMI ' + ttFmt(r.bmi, 1) + '.';\n      function done() { var n = $('copy_note'); n.classList.remove('hidden'); setTimeout(function () { n.classList.add('hidden'); }, 1800); }\n      if (navigator.clipboard && navigator.clipboard.writeText) {\n        navigator.clipboard.writeText(txt).then(done, done);\n      } else {\n        var ta = document.createElement('textarea');\n        ta.value = txt; document.body.appendChild(ta); ta.select();\n        try { document.execCommand('copy'); } catch (e) {}\n        ta.remove(); done();\n      }\n    });\n    $('goal_toggle').addEventListener('click', function () {\n      state.goalOn = !state.goalOn;\n      $('goal_toggle').setAttribute('aria-checked', state.goalOn ? 'true' : 'false');\n      $('goal_body').classList.toggle('hidden', !state.goalOn);\n      renderGoal(ttCompute(state.sex, state.unit, readInputs()));\n    });\n    function syncGoal(fromSlider) {\n      if (fromSlider) $('in_goal_num').value = $('in_goal').value;\n      else $('in_goal').value = $('in_goal_num').value;\n      renderGoal(ttCompute(state.sex, state.unit, readInputs()));\n    }\n    $('in_goal').addEventListener('input', function () { syncGoal(true); });\n    $('in_goal_num').addEventListener('input', function () { syncGoal(false); });\n    document.querySelectorAll('.faq-item').forEach(function (item) {\n      var btn = item.querySelector('.faq-q');\n      btn.addEventListener('click', function () {\n        var open = item.classList.toggle('open');\n        btn.setAttribute('aria-expanded', open ? 'true' : 'false');\n      });\n    });\n  }\n\n  loadState();\n  renderHistory();\n  wire();\n  recalc();\n})();\n</script>\n</body>\n</html>\n";
export default {
  async fetch(request) {
    const url = new URL(request.url);
    if (url.pathname !== "/" && url.pathname !== "/index.html") {
      return new Response("Not found", { status: 404 });
    }
    return new Response(HTML, {
      headers: { "content-type": "text/html;charset=UTF-8" }
    });
  }
};